def tuple_intersection(test_list1, test_list2):
    # Normalize each tuple by sorting its elements so (4, 5) and (5, 4) match,
    # then return the set of normalized tuples present in both lists.
    set1 = {tuple(sorted(t)) for t in test_list1}
    set2 = {tuple(sorted(t)) for t in test_list2}
    return set1 & set2


